    "277bdb80": {"text":"0;) { const a = FBDATA.ailments[c.ails[i]]; if (a && a.kind === tipo) { c.ails.splice(i, 1); izquierda--; } más i++; } if (!c.ails.length) eliminar c.ails; }; FB.randomWound = función (sev) { const pool = []; for (id constante en FBDATA.ailments) { const a = FBDATA.ailments[id]; if (a.kind === 'herida' && (a.sev || 1) === sev) pool.push(id); } devolver piscina.longitud? FB.pick(grupo): nulo; }; FB.randomSickness = function () { const pool = []; for (const id en FBDATA.ailments) { if (FBDATA.ailments[id].kind === 'enfermedad') pool.push(id); } devolver piscina.longitud? FB.pick(grupo): nulo; }; FB.traitAgg = función (c) { const agg = { dip: 0, mar: 0, ste: 0, int: 0, lea: 0, salud: 0, fert: 1, opinión: 0 }; for (id constante de c.traits) { const t = FBDATA.traits[id]; si (!t) continúa; for (const s de HABILIDADES) if (t[s]) agg[s] += t[s]; if (t.salud) agg.salud += t.salud; if (t.fert) agg.fert *= t.fert; if (t.opinion) agg.opinion += t.opinion; } devolver valor; }; función baseSkill(c, clave) {si (!c) devuelve 0; habilidades constantes = c.habilidades || {}; return (habilidades[clave] || 0) + (FB.traitAgg(c)[clave] || 0); } FB.skillOf = función (c, clave) { let v = baseSkill(c, clave); // El equipo doméstico equipado agudiza a quien lo usa (FB.itemBonus se carga más tarde). if (c && FB.state && FB.itemBonus && FB.state.chars && FB.state.chars[c.id] === c) v += FB.itemBonus(FB.state, clave, c.id); devolver Math.max(0, v); }; FB.skillSnapshot = función (estado, c, clave) { let v = baseSkill(c, clave); if (estado && c && FB.itemBonusReadOnly && state.chars && state.chars[c.id] === c) { v += FB.itemBonusReadOnly(estado, clave, c.id); } devolver Math.max(0, v); }; /* El crecimiento de habilidades no tiene límite. Debajo de balance.skillSoftCap aparecen todas las ganancias; más allá de él, cada punto debe superar un rollo (softCap/current)^2. En balance.skillMasteryThreshold y más allá, esa posibilidad se multiplica aún más por (masteryThreshold/current)^skillMasteryPower. Sólo la habilidad cruda y entrenada establece estas probabilidades; Los rasgos y el equipo no hacen que el entrenamiento sea más difícil. Devuelve los puntos realmente ganados. */ FB.gainSkill = función (c, clave, n) { const B = FBDATA.balance; constante suave = B.skillSoftCap || 20; dominio constante = B.skillMasteryThreshold || 40; potencia constante = B.skillMasteryPower! == indefinido? B.skillMasteryPower: 8; dejar ganado = 0; para (sea i = 0; i","hash":"h1-b90ffcec"},
