    "52e6ce3c": {"text":"brindis evento-recibo-brindis","hash":"h1-064f1b13"},
    "52e95862": {"text":"Almacenes","hash":"h1-8ee44255"},
    "52eddd8b": {"text":"Esta unión ya se ha hecho.","hash":"h1-e26fbf5d"},
