    "7b1a18a6": {"text":"matrimonio del clero","hash":"h1-d1be114f"},
    "7b1c5841": {"text":"Quimper","hash":"h1-3d8cd9f4"},
    "7b1e42ac": {"text":"Compré reconocimiento por el estilo de la casa.","hash":"h1-413caa2a"},
