    "a951db45": {"forms":{"select":"plural","param":"count","cases":{"one":"📜 El sucesor hereda una obligación activa, que ahora vale {money:amount}.","other":"📜 El sucesor hereda obligaciones activas {count}, que ahora valen {money:amount}."}},"hash":"h1-c75646a1"},
