    "d9c85a3c": {"text":"— vuelve al rango básico cuando no se aterriza */ FB.styledTitle = function (state) { return FB.renderTitleSnapshot(FB.titleSnapshot(state)); }; FB.titleSnapshot = función (estado) { const p = estado.player; const me = estado.chars[p.charId]; rango constante = rangoTitleRecord(estado, yo.religión, yo.sexo, p.tier); let grupo = FB.faithGroup(me.religión, estado) || 'cristiano'; if (me.sex === 'f' && FBDATA.titles[grupo + '_f']) grupo += '_f'; const snap = { grupo:grupo, religión:yo.religión, títuloReligión:rank.sourceId || nulo, títuloSexo:rank.sex || yo.sexo, nivel:rango.nivel, palabra:rango.palabra }; if (FB.playerPope && FB.playerPope(estado)) { snap.headReligion = yo.religion; const head = FB.faithValue(estado, yo.religión, 'head.title'); snap.headTitleReligion = head.sourceId || yo.religión; snap.headTitle = head.valor || 'Papa'; chasquido de retorno; } if (FB.playerCardinal && FB.playerCardinal(estado)) { snap.special = 'cardinal'; instantáneaFaithRole(snap, estado, me.religion, 'cardenal'); chasquido de retorno; } const encabezado = FB.religionsHeadedBy(estado, 'jugador'); if (encabezado.longitud) { const headReligion = encabezado[0]; snap.headReligion = cabezaReligión; const head = FB.faithValue(estado, headReligion, 'head.title'); snap.headTitleReligion = head.sourceId || cabezaReligión; snap.headTitle = cabeza.valor; chasquido de retorno; } si (p.tier","hash":"h1-cfe3bc23"},
    "d9d7fc22": {"text":"⛓ Sacrilegio: atacar al Papado activo conlleva la excomunión, pierde toda piedad y pone a todos los gobernantes católicos en su contra.","hash":"h1-8b55faa1"},
