    "f0387ef0": {"text":"⛪ {name} se crea Cardenal de {title}.","hash":"h1-ff324804"},
    "f038fa91": {"text":"Sin estudio dirigido","hash":"h1-d3ad89a3"},
    "f039927b": {"text":"Oro gastado ahora","hash":"h1-fdcd3baf"},
